// Every Unity script must inherit from MonoBehaviour
public class PlayerMovement : MonoBehaviour
{
    // [SerializeField] exposes private fields in the Inspector
    // without making them public to other scripts
    [SerializeField] private float moveSpeed = 5f;
    [SerializeField] private float jumpForce = 10f;

    // Reference to the Rigidbody component
    private Rigidbody rb;

    void Awake()
    {
        // GetComponent finds a component on the same GameObject
        rb = GetComponent<Rigidbody>();

        // Safety check: what if someone forgot to add Rigidbody?
        if (rb == null)
        {
            Debug.LogError("Rigidbody missing! Add one to this GameObject.");
            enabled = false; // Disable this script
        }
    }

    void Update()
    {
        // Get input axes (-1 to 1)
        float horizontal = Input.GetAxis("Horizontal");
        float vertical = Input.GetAxis("Vertical");

        // Create movement vector
        Vector3 movement = new Vector3(horizontal, 0f, vertical);

        // Apply movement
        // Time.deltaTime makes movement frame-rate independent
        transform.position += movement * moveSpeed * Time.deltaTime;

        // Jump on spacebar press
        if (Input.GetKeyDown(KeyCode.Space))
        {
            rb.AddForce(Vector3.up * jumpForce, ForceMode.Impulse);
        }
    }
}

