    }
}

using UnityEngine;

[RequireComponent(typeof(Animator))]
public class AnimationController : MonoBehaviour
{
    private Animator animator;
    private int isWalkingHash;
    private int speedHash;
    private int attackTriggerHash;

    void Awake()
    {
        animator = GetComponent<Animator>();

        // Cache parameter hashes for performance
        // Using hashes is faster than string lookups every frame
        isWalkingHash = Animator.StringToHash("IsWalking");
        speedHash = Animator.StringToHash("Speed");
        attackTriggerHash = Animator.StringToHash("Attack");
    }

    void Update()
    {
        float speed = Input.GetAxis("Vertical");
        bool isWalking = Mathf.Abs(speed) > 0.1f;

        // Set bool parameter
        animator.SetBool(isWalkingHash, isWalking);

        // Set float parameter (for blend trees)
        animator.SetFloat(speedHash, Mathf.Abs(speed));

        // Set trigger parameter (auto-resets after transition)
        if (Input.GetButtonDown("Fire1"))
        {
            animator.SetTrigger(attackTriggerHash);
        }

        // Reset trigger manually if needed
        if (Input.GetButtonUp("Fire1"))
        {
            animator.ResetTrigger(attackTriggerHash);
        }
    }

    // Called by Animation Event (set in animation clip)
    public void OnAttackHit()
    {
        // Deal damage at exact frame of animation
        Debug.Log("Attack landed!");
    }

    // Check current state
    bool IsInState(string stateName)
    {
        return animator.GetCurrentAnimatorStateInfo(0).IsName(stateName);
    }

    // Check if transition is happening
    bool IsTransitioning()
    {
        return animator.IsInTransition(0);
    }
}

