using UnityEngine;

public class BlendTreeController : MonoBehaviour
{
    private Animator animator;
    private int velocityXHash;
    private int velocityZHash;

    void Awake()
    {
        animator = GetComponent<Animator>();
        velocityXHash = Animator.StringToHash("VelocityX");
        velocityZHash = Animator.StringToHash("VelocityZ");
    }

    void Update()
    {
        // Get input relative to camera
        float h = Input.GetAxis("Horizontal");
        float v = Input.GetAxis("Vertical");

        // Convert to camera-relative direction
        Vector3 cameraForward = Camera.main.transform.forward;
        Vector3 cameraRight = Camera.main.transform.right;
        cameraForward.y = 0;
        cameraRight.y = 0;
        cameraForward.Normalize();
        cameraRight.Normalize();

        Vector3 moveDir = (cameraForward * v + cameraRight * h).normalized;

        // Transform world direction to local direction relative to player
        Vector3 localDir = transform.InverseTransformDirection(moveDir);

        // Set blend tree parameters (-1 to 1 range)
        animator.SetFloat(velocityXHash, localDir.x);
        animator.SetFloat(velocityZHash, localDir.z);

        // For 1D blend tree (speed-based)
        float speed = new Vector2(h, v).magnitude;
        animator.SetFloat("Speed", speed);
    }
}

// 2D Sprite Animation (for 2D games)
public class SpriteAnimator : MonoBehaviour
{
    private Animator animator;
    private SpriteRenderer spriteRenderer;
    private int directionHash;

    void Awake()
    {
        animator = GetComponent<Animator>();
        spriteRenderer = GetComponent<SpriteRenderer>();
        directionHash = Animator.StringToHash("Direction");
    }

    void Update()
    {
        float h = Input.GetAxisRaw("Horizontal");
        float v = Input.GetAxisRaw("Vertical");

        // 0=Down, 1=Up, 2=Left, 3=Right
        int direction = 0;
        if (v > 0) direction = 1;
        else if (v < 0) direction = 0;
        else if (h < 0) direction = 2;
        else if (h > 0) direction = 3;

        animator.SetInteger(directionHash, direction);
        animator.SetBool("IsMoving", h != 0 || v != 0);

        // Flip sprite for left/right without separate animations
        if (h < 0) spriteRenderer.flipX = true;
        else if (h > 0) spriteRenderer.flipX = false;
    }
}

using UnityEngine;
using UnityEngine.Audio;

public class AudioManager : MonoBehaviour
{
    public static AudioManager Instance { get; private set; }

    [Header("Audio Mixers")]
    [SerializeField] private AudioMixer mainMixer;

    [Header("Sound Pools")]
    [SerializeField] private AudioSource sfxSource;
    [SerializeField] private AudioSource musicSource;
    [SerializeField] private AudioSource voiceSource;

    [Header("Sound Clips")]
    [SerializeField] private AudioClip jumpClip;
    [SerializeField] private AudioClip landClip;
    [SerializeField] private AudioClip[] footstepClips;

    void Awake()
    {
        // Singleton pattern
        if (Instance != null && Instance != this)
        {
            Destroy(gameObject);
            return;
        }
        Instance = this;
        DontDestroyOnLoad(gameObject);
    }

    public void PlaySFX(AudioClip clip, float volume = 1f, float pitch = 1f)
    {
        if (clip == null) return;

        sfxSource.pitch = pitch;
        sfxSource.PlayOneShot(clip, volume);
    }

    public void PlayRandomFootstep()
    {
        if (footstepClips.Length == 0) return;
        AudioClip clip = footstepClips[Random.Range(0, footstepClips.Length)];
        float randomPitch = Random.Range(0.9f, 1.1f);
        PlaySFX(clip, 0.5f, randomPitch);
    }

    public void PlayMusic(AudioClip music, bool loop = true)
    {
        if (musicSource.isPlaying) musicSource.Stop();
        musicSource.clip = music;
        musicSource.loop = loop;
        musicSource.Play();
    }

    public void PlayAtPosition(AudioClip clip, Vector3 position, float volume = 1f)
    {
        // Creates temporary AudioSource that auto-destroys when done
        AudioSource.PlayClipAtPoint(clip, position, volume);
    }

    public void SetVolume(string mixerGroup, float volume)
    {
        // Convert 0-1 slider to decibels (-80 to 0)
        float dB = volume > 0 ? Mathf.Log10(volume) * 20 : -80f;
        mainMixer.SetFloat(mixerGroup, dB);
    }

    public void FadeOutMusic(float duration)
    {
        StartCoroutine(FadeMusic(musicSource, 0f, duration));
    }

    private System.Collections.IEnumerator FadeMusic(AudioSource source, float targetVolume, float duration)
    {
        float startVolume = source.volume;
        float elapsed = 0f;

        while (elapsed < duration)
        {
            elapsed += Time.deltaTime;
            source.volume = Mathf.Lerp(startVolume, targetVolume, elapsed / duration);
            yield return null;
        }

        source.volume = targetVolume;
        if (targetVolume <= 0) source.Stop();
    }
}

