        PlayerHealth.OnDamageTaken += ShowDamageFlash;
        GameManager.OnScoreChanged += UpdateScore;
    }

    void OnDestroy()
    {
        // Always unsubscribe
        PlayerHealth.OnHealthChanged -= UpdateHealthUI;
        PlayerHealth.OnDamageTaken -= ShowDamageFlash;
        GameManager.OnScoreChanged -= UpdateScore;
    }

    void UpdateHealthUI(int current, int max)
    {
        healthText.text = $"{current} / {max}";
        healthBar.value = (float)current / max;
    }

    void ShowDamageFlash(float damageAmount)
    {
        // Flash red when taking damage
        damageFlash.color = new Color(1, 0, 0, 0.5f);
        StartCoroutine(FadeOut(damageFlash, 0.5f));
    }

    void UpdateScore(int score)
    {
        // Animate score counting up
        StartCoroutine(AnimateScore(score));
    }

    public void ShowDamageNumber(Vector3 worldPosition, float damage)
    {
        // Spawn world-space damage number
        GameObject number = Instantiate(damageNumberPrefab, worldPosition, Quaternion.identity);

        // Billboard — always face camera
        number.transform.LookAt(number.transform.position + Camera.main.transform.rotation * Vector3.forward,
                                  Camera.main.transform.rotation * Vector3.up);

        TextMeshPro tmp = number.GetComponent<TextMeshPro>();
        tmp.text = $"-{damage:F0}";
        tmp.color = damage > 50 ? Color.red : Color.yellow;

        Destroy(number, 1.5f);
    }

    public void TogglePause()
    {
        pauseMenu.SetActive(!pauseMenu.activeSelf);
        Time.timeScale = pauseMenu.activeSelf ? 0f : 1f;
    }

    public void ShowGameOver()
    {
        gameOverPanel.SetActive(true);
        // Animate panel scale up
        gameOverPanel.transform.localScale = Vector3.zero;
        StartCoroutine(ScaleUp(gameOverPanel.transform, 0.3f));
    }

    // Button click handlers (assign in Inspector)
    public void OnRestartClicked()
    {
        SceneManager.LoadScene(SceneManager.GetActiveScene().buildIndex);
    }

    public void OnQuitClicked()
    {
        Application.Quit();
    }

    private System.Collections.IEnumerator FadeOut(Image image, float duration)
    {
        Color start = image.color;
        float elapsed = 0f;

        while (elapsed < duration)
        {
            elapsed += Time.deltaTime;
            float alpha = Mathf.Lerp(start.a, 0f, elapsed / duration);
            image.color = new Color(start.r, start.g, start.b, alpha);
            yield return null;
        }
    }

    private System.Collections.IEnumerator AnimateScore(int target)
    {
        int current = int.Parse(scoreText.text);
        float duration = 0.5f;
        float elapsed = 0f;

        while (elapsed < duration)
        {
            elapsed += Time.deltaTime;
            int display = Mathf.RoundToInt(Mathf.Lerp(current, target, elapsed / duration));
            scoreText.text = display.ToString();
            yield return null;
        }
        scoreText.text = target.ToString();
    }

    private System.Collections.IEnumerator ScaleUp(Transform target, float duration)
    {
        float elapsed = 0f;
        while (elapsed < duration)
        {
            elapsed += Time.deltaTime;
            target.localScale = Vector3.Lerp(Vector3.zero, Vector3.one, elapsed / duration);
            yield return null;
        }
        target.localScale = Vector3.one;
    }
}

using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.UI;

public class SceneLoader : MonoBehaviour
{
    [SerializeField] private GameObject loadingScreen;
    [SerializeField] private Slider progressBar;
    [SerializeField] private TextMeshProUGUI progressText;

    public void LoadLevel(string sceneName)
    {
        StartCoroutine(LoadAsync(sceneName));
    }

    private System.Collections.IEnumerator LoadAsync(string sceneName)
    {
        // Show loading screen
        loadingScreen.SetActive(true);

        // Begin async load
        AsyncOperation operation = SceneManager.LoadSceneAsync(sceneName);

        // Prevent scene from activating immediately when ready
        operation.allowSceneActivation = false;

        // Progress goes 0 → 0.9 while loading, then jumps to 1.0 when activated
        while (operation.progress < 0.9f)
        {
            float progress = Mathf.Clamp01(operation.progress / 0.9f);
            UpdateProgressUI(progress);
            yield return null;
        }

        // Loading complete, show 100%
        UpdateProgressUI(1f);

        // Optional: wait for input or minimum display time
        yield return new WaitForSeconds(0.5f);

        // Activate the scene
        operation.allowSceneActivation = true;
    }

    void UpdateProgressUI(float progress)
    {
        progressBar.value = progress;
        progressText.text = $"{progress * 100:F0}%";
    }

    public void LoadAdditive(string overlayScene)
    {
        // Load UI or additional content without unloading current scene
        SceneManager.LoadScene(overlayScene, LoadSceneMode.Additive);
    }

    public void UnloadAdditive(string sceneName)
    {
        SceneManager.UnloadSceneAsync(sceneName);
    }

    public void ReloadCurrentScene()
    {
        SceneManager.LoadScene(SceneManager.GetActiveScene().buildIndex);
    }

    public void QuitGame()
    {
        #if UNITY_EDITOR
            UnityEditor.EditorApplication.isPlaying = false;
        #else
            Application.Quit();
        #endif
    }
}

