    public Sprite weaponIcon;

    [Header("Combat Stats")]
    public float damage = 25f;
    public float fireRate = 0.1f; // Seconds between shots
    public float range = 100f;
    public int magazineSize = 30;

    [Header("Recoil & Spread")]
    public float recoilVertical = 2f;
    public float recoilHorizontal = 0.5f;
    public float spreadBase = 0.01f;
    public float spreadMax = 0.1f;

    [Header("Audio & Visual")]
    public AudioClip fireSound;
    public ParticleSystem muzzleFlashPrefab;
    public GameObject impactEffectPrefab;
}

// Usage in a weapon script
public class Weapon : MonoBehaviour
{
    [SerializeField] private WeaponData weaponData;
    private int currentAmmo;
    private float lastFireTime;

    void Start()
    {
        currentAmmo = weaponData.magazineSize;
    }

    void Update()
    {
        if (Input.GetButton("Fire1") && Time.time >= lastFireTime + weaponData.fireRate)
        {
            Fire();
        }
    }

    void Fire()
    {
        if (currentAmmo <= 0) return;

        currentAmmo--;
        lastFireTime = Time.time;

        // Apply damage with configured stats
        RaycastHit hit;
        if (Physics.Raycast(transform.position, transform.forward, out hit, weaponData.range))
        {
            IDamageable target = hit.collider.GetComponent<IDamageable>();
            target?.TakeDamage(weaponData.damage);

            // Spawn impact effect from ScriptableObject
            Instantiate(weaponData.impactEffectPrefab, hit.point, Quaternion.LookRotation(hit.normal));
        }

        // Play sound
        AudioManager.Instance.PlaySFX(weaponData.fireSound);
    }
}
